// GCC/Clang Attribute: Simulating RAII/Destructors

void resource_free(void **ptr) {
    if (*ptr) free(*ptr);
}

// Local variable decorated with cleanup routine
void *data_buffer
    __attribute__((cleanup(resource_free))) = NULL;

data_buffer = malloc(1024);
// ... Use data_buffer ...

// Cleanup function `resource_free` is automatically
// executed when `data_buffer` goes out of scope.
